using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
public sealed class RoadMapIssue {public bool error;public string id,message;public Vector3 position;public override string ToString(){return (error?"오류":"경고")+" · "+id+" · "+message;}}
public static class RoadMapValidator {
 [Serializable] sealed class Points {public MapPoint[] points;} static bool Finite(float x){return !float.IsNaN(x)&&!float.IsInfinity(x);}
 public static List<RoadMapIssue> Validate(MapData baseline,RoadMapDocument d){try{return ValidateCore(baseline,d);}catch(Exception ex){return new List<RoadMapIssue>{new RoadMapIssue{error=true,id="문서 구조",message="손상/미지원 자료를 수정하거나 정상본 복원: "+ex.Message}};}} static List<RoadMapIssue> ValidateCore(MapData baseline,RoadMapDocument d){var issues=new List<RoadMapIssue>();Action<string,string,bool,Vector3> add=(id,msg,error,p)=>issues.Add(new RoadMapIssue{id=id,message=msg,error=error,position=p});
  if(d==null){add("문서","수정본을 불러오세요",true,Vector3.zero);return issues;}
  if(d.schema!=1||d.mapId!=baseline.mapId||d.baseHash!=RoadMapRuntime.Hash(baseline))add("기준 지도","스키마/지도ID/해시 불일치 · 동일 빌드의 수정본을 사용하거나 기본 지도로 복원하세요",true,Vector3.zero);
  if(d.lanes==null||d.facilities==null||d.signals==null){add("문서","필수 배열 누락",true,Vector3.zero);return issues;}
  issues.AddRange(ProjectMapScene.Validate(baseline,d));
  var geometry=baseline;if(d.scene!=null&&!issues.Any(i=>i.error)){geometry=JsonUtility.FromJson<MapData>(JsonUtility.ToJson(baseline));ProjectMapScene.Apply(geometry,d.scene);}
  var originals=baseline.hdEdges.ToDictionary(e=>e.id);var lanes=new Dictionary<string,RoadMapLane>();foreach(var l in d.lanes){if(l==null||string.IsNullOrWhiteSpace(l.id)||lanes.ContainsKey(l.id)){add("차로ID","없는/중복 ID를 수정하세요",true,Vector3.zero);continue;}lanes.Add(l.id,l);}
  foreach(var e in baseline.hdEdges)if(!lanes.ContainsKey(e.id))add(e.id,"기준 차로 누락 · 삭제 대신 비활성화하세요",true,e.points[0].V());
  foreach(var l in lanes.Values){var p=l.points!=null&&l.points.Length>0?l.points[0].V():Vector3.zero;
   if(!Finite(l.width)||l.width<2.6f||l.width>5)add(l.id,"폭은 2.6~5m로 입력하세요",true,p);
   if(l.points==null||l.points.Length<2||l.points.Any(v=>v==null||!Finite(v.x)||!Finite(v.z))){add(l.id,"유효한 제어점 2개 이상 필요",true,p);continue;}
   if((!originals.ContainsKey(l.id)||JsonUtility.ToJson(new Points{points=originals[l.id].points})!=JsonUtility.ToJson(new Points{points=l.points}))&&l.points.Any(v=>v.x<0||v.z<0||v.x>baseline.width||v.z>baseline.depth))add(l.id,"지도 경계 밖 제어점",true,p);
   if(l.heights!=null&&l.heights.Length!=0&&l.heights.Length!=l.points.Length)add(l.id,"제어점/높이 배열 길이 불일치",true,p);if(l.heights!=null&&l.heights.Any(h=>!Finite(h)||h<0||h>1.5f))add(l.id,"높이는 지면 기준0~1.5m",true,p);if(l.next==null){add(l.id,"연결 목록 누락",true,p);continue;}if(l.disabled)continue;
   if(l.turn< -1||l.turn>1||l.change< -1||l.change>1)add(l.id,"유턴/미지원 진행값 · 좌/직/우만 지원",true,p);
   HdEdge original;bool geometryChanged=!originals.TryGetValue(l.id,out original)||JsonUtility.ToJson(new Points{points=original.points})!=JsonUtility.ToJson(new Points{points=l.points});if(geometryChanged)for(int a=1;a<l.points.Length;a++){if(Vector3.Distance(l.points[a-1].V(),l.points[a].V())<.001f)add(l.id,"중복 제어점을 분리하세요",true,p);for(int b=a+2;b<l.points.Length;b++)if(Cross(l.points[a-1].V(),l.points[a].V(),l.points[b-1].V(),l.points[b].V()))add(l.id,"자기 교차 제어점 수정",true,p);}
   if(geometryChanged&&!l.disabled){bool blocked=false;var path=new AssistedRoadNetwork.Path(l.points.Select(q=>q.V()).ToArray());for(float at=0;at<=path.length&&!blocked;at+=2){var q=path.Position(at);var side=TrafficSystem.Right(path.Tangent(at));foreach(float offset in new[]{-l.width*.5f,0,l.width*.5f}){var sample=q+side*offset;if(ReviewedPavement.Contains(geometry,sample)){add(l.id,"검토 보도/자전거도로 침범 · 제어점을 이동하세요",true,sample);blocked=true;break;}foreach(var b in geometry.buildings){if(sample.x<b.points.Min(v=>v.x)||sample.x>b.points.Max(v=>v.x)||sample.z<b.points.Min(v=>v.z)||sample.z>b.points.Max(v=>v.z))continue;if(RoadMapRules.Polygon(b.points,sample)&&!SceneBuildingVisibility.Hidden(geometry,b.id)){add(l.id,"건물 "+b.id+" 침범 · 제어점을 이동하세요",true,sample);blocked=true;break;}}}}}foreach(string id in l.next){RoadMapLane n;if(!lanes.TryGetValue(id??"",out n)){add(l.id,"없는 출구 "+id+" · 다시 연결하세요",true,p);continue;}if(n.disabled){add(l.id,"삭제된 출구 "+id+" · 연결 제거/대상 재지정",true,p);continue;}if(n.points==null||n.points.Length<2)continue;float endHeight=l.heights!=null&&l.heights.Length==l.points.Length?l.heights.Last():0,startHeight=n.heights!=null&&n.heights.Length==n.points.Length?n.heights[0]:0;if(l.toNode!=n.fromNode||Mathf.Abs(endHeight-startHeight)>.15f||Vector3.Distance(l.points.Last().V(),n.points[0].V())>.15f)add(l.id,"끝점 단절: "+id+" · 같은 노드 제어점에 맞추세요",true,l.points.Last().V());
    var a=(l.points.Last().V()-l.points[l.points.Length-2].V()).normalized;var b=(n.points[1].V()-n.points[0].V()).normalized;if(Vector3.Dot(a,b)<-.8f)add(l.id,"반대 방향 연결 · 유턴은 미지원",true,l.points.Last().V());}
   if(l.next.Length==0&&baseline.hdEdges.Any(e=>e.id==l.id&&!e.disabled&&e.next.Length>0))add(l.id,"출구 연결이 없습니다 · 최소 한 개 연결",true,l.points.Last().V());
   if(l.evidence==null||l.evidence.state!="observed"||string.IsNullOrWhiteSpace(l.evidence.month)){} // Existing unedited lanes retain their source status; selected edits show evidence warnings in the panel.
  }
  var ids=new HashSet<string>(lanes.Keys);foreach(var f in d.facilities){if(f==null||string.IsNullOrWhiteSpace(f.id)||!ids.Add(f.id)){add("시설","없는/중복 ID",true,Vector3.zero);continue;}var p=f.Position;if(!new[]{"sign","stopLine","crosswalk","line","centreLine","vehicleSignal","pedestrianSignal"}.Contains(f.kind)||f.x<0||f.z<0||f.x>baseline.width||f.z>baseline.depth)add(f.id,"미지원 시설 종류 또는 지도 밖 위치",true,p);
   if(!Finite(f.x)||!Finite(f.z)||!Finite(f.height)||!Finite(f.width)||!Finite(f.length)||!Finite(f.scale)||!Finite(f.yaw)||f.width<=0||f.width>40||f.length<=0||f.length>40||f.scale<.1f||f.scale>5||f.height<0||f.height>12)add(f.id,"위치/폭/길이/높이/크기 범위를 확인하세요",true,p);
   if(f.axis<0||f.axis>1||Math.Abs(f.sign)!=1)add(f.id,"축0/1 · 방향±1 필요",true,p);
   if(!string.IsNullOrEmpty(f.laneId)&&(!lanes.ContainsKey(f.laneId)||lanes[f.laneId].disabled))add(f.id,"없는 차로 · 대상을 다시 지정하세요",true,p);
   if(f.kind=="vehicleSignal"||f.kind=="pedestrianSignal"){var program=d.signals.FirstOrDefault(s=>s.junctionId==f.junctionId);var group=program==null?null:program.groups.FirstOrDefault(g=>g.id==f.groupId);if(group==null||group.pedestrian!=(f.kind=="pedestrianSignal"))add(f.id,"신호 그룹/종류를 연결하세요",true,p);if(f.kind=="vehicleSignal"&&!d.facilities.Any(x=>x.id==f.targetId&&x.kind=="stopLine"))add(f.id,"제어 정지선을 연결하세요",true,p);if(f.kind=="pedestrianSignal"&&!d.facilities.Any(x=>x.id==f.targetId&&x.kind=="crosswalk"))add(f.id,"제어 횡단보도를 연결하세요",true,p);}
   if(f.rule&&f.kind=="sign"){if(f.type!="진입 금지"&&f.type!="좌회전 금지"&&f.type!="우회전 금지"&&f.type!="제한속도")add(f.id,"이 표지는 안내용만 지원 · 규칙 적용 해제",true,p);if(string.IsNullOrEmpty(f.laneId))add(f.id,"규칙 적용 차로를 지정하세요",true,p);}
   if(f.rule&&f.type=="제한속도"){RoadMapLane target;if(!Finite(f.speed)||f.speed<5||f.speed>100||!Finite(f.startAt)||!Finite(f.endAt)||f.startAt<0||f.endAt<=f.startAt)add(f.id,"제한속도/적용 시작·끝 범위 오류",true,p);if(lanes.TryGetValue(f.laneId,out target)&&target.points!=null&&target.points.Length>1&&f.endAt>new AssistedRoadNetwork.Path(target.points.Select(q=>q.V()).ToArray()).length)add(f.id,"제한속도 끝이 차로 길이를 넘습니다",true,p);if(d.facilities.Any(g=>g!=f&&g.rule&&g.type=="제한속도"&&g.laneId==f.laneId&&g.startAt<f.endAt&&f.startAt<g.endAt&&g.speed!=f.speed))add(f.id,"겹치는 제한속도 상충",true,p);}if(f.evidence==null||f.evidence.state!="observed"||string.IsNullOrWhiteSpace(f.evidence.month))add(f.id,"현장/촬영월 미확인 · 게임 설정",false,p);
  }
  var rules=baseline.junctionRules??new HybridJunctionRule[0];var signalIds=new HashSet<string>();foreach(var program in d.signals){if(program==null||!signalIds.Add(program.junctionId??"")){add("신호","없는/중복 교차로 프로그램",true,Vector3.zero);continue;}var rule=rules.FirstOrDefault(r=>r.id==program.junctionId);var p=rule==null?Vector3.zero:rule.V();if(rule==null){add(program.junctionId,"없는 교차로",true,p);continue;}
   if(program.groups==null||program.groups.Length==0||program.stages==null||program.stages.Length==0){add(program.junctionId,"그룹/단계를 추가하세요",true,p);continue;}var groupIds=new HashSet<string>();foreach(var g in program.groups){if(g==null||string.IsNullOrEmpty(g.id)||!groupIds.Add(g.id)){add(program.junctionId,"그룹ID 중복/누락",true,p);continue;}if(!program.stages.Any(s=>s!=null&&s.groups!=null&&s.groups.Contains(g.id)))add(g.id,"한 번도 허용되지 않는 그룹 · 단계에 연결하세요",true,p);if(g.axis<0||g.axis>1||Math.Abs(g.sign)!=1||g.turn< -1||g.turn>1)add(g.id,"미지원 신호 진행",true,p);if(g.pedestrian&&!d.facilities.Any(f=>f.id==g.crosswalkId&&f.kind=="crosswalk"&&f.junctionId==program.junctionId))add(g.id,"보행 그룹의 횡단보도ID를 연결하세요",true,p);foreach(var laneId in g.laneIds??new string[0])if(!lanes.ContainsKey(laneId)||lanes[laneId].disabled)add(g.id,"그룹 차로 참조 오류",true,p);}
   foreach(var stage in program.stages){if(stage==null||!Finite(stage.green)||!Finite(stage.yellow)||!Finite(stage.clearance)||stage.green<=0||stage.green>120||stage.yellow<0||stage.yellow>10||stage.clearance<1||stage.clearance>30){add(program.junctionId,"단계 시간: 녹색1~120/황색0~10/정리1~30초",true,p);continue;}if(stage.groups==null){add(program.junctionId,"단계 그룹 목록 누락",true,p);continue;}foreach(var id in stage.groups)if(!groupIds.Contains(id))add(id,"없는 단계 그룹",true,p);
    var active=program.groups.Where(g=>g!=null&&stage.groups.Contains(g.id)).ToArray();for(int a=0;a<active.Length;a++)for(int b=a+1;b<active.Length;b++)if(Conflict(active[a],active[b]))add(program.junctionId,"상충 단계: "+active[a].name+" / "+active[b].name+" · 단계를 분리하세요",true,p);
   }
  }
  if(!issues.Any(i=>i.error))try{var candidate=RoadMapComposer.Compose(baseline,d);var graph=new HdRoadGraph(candidate);for(int a=0;a<candidate.stops.Length;a++)for(int b=0;b<candidate.stops.Length;b++){if(a==b)continue;var s=candidate.stops[a];var t=candidate.stops[b];if(s.graphStop&&t.graphStop&&graph.Route(s.laneEdge,s.laneAt,t.laneEdge,t.laneAt)==null){add("승하차/거점 "+a+"→"+b,"필수 접근 불가 · 차로 연결을 복원하세요",true,s.V());return issues;}}if(d.scene!=null)foreach(var service in d.scene.objects.Where(o=>o.enabled&&o.IsService)){var approach=ProjectMapScene.ServiceStop(candidate,service);foreach(var stop in candidate.stops){if(!stop.graphStop||stop.laneEdge==approach.laneEdge&&Mathf.Abs(stop.laneAt-approach.laneAt)<.15f)continue;if(graph.Route(stop.laneEdge,stop.laneAt,approach.laneEdge,approach.laneAt)==null||graph.Route(approach.laneEdge,approach.laneAt,stop.laneEdge,stop.laneAt)==null){add(service.id,"승하차 지점과 시설의 왕복 접근 불가 · 차로 연결을 복원하세요",true,service.Position);break;}}}FuelStationLayout.Apply(candidate);}catch(Exception ex){add("지도 구성",ex.Message,true,Vector3.zero);}
  return issues;
 }
 public static bool Conflict(RoadMapSignalGroup a,RoadMapSignalGroup b){if(a.pedestrian&&b.pedestrian)return false;if(a.pedestrian!=b.pedestrian)return true;if(a.axis!=b.axis)return true;if(a.sign==b.sign)return false;return a.turn!=0||b.turn!=0;}
 public static bool Cross(Vector3 a,Vector3 b,Vector3 c,Vector3 d){return Side(a,b,c)*Side(a,b,d)<-.0001f&&Side(c,d,a)*Side(c,d,b)<-.0001f;}
 static float Side(Vector3 a,Vector3 b,Vector3 c){return (b.x-a.x)*(c.z-a.z)-(b.z-a.z)*(c.x-a.x);}
}
